def bl(cid, shelf, **kw):
    row = dict(region="Italy", seen="catalogue", source="British Library catalogue sweep", score_note=SNB, prior_art=PAB,
               shelfmark=shelf, links=[{"label": f"BL catalogue {shelf}", "href": BLC + cid}])
    row.update(kw)
    return row


